import { jsPDF } from "jspdf";
import logo from "../../icons/logo1.png";


export const generatePdf = async (teethList, imageElement) => {

    const teethWithImages = await cropTeethFromRadiograph(imageElement, teethList);

    const doc = new jsPDF();

    doc.setFontSize(16);

    const base64Image = await convertImgToBase64FromImport(logo);
    doc.addImage(base64Image, 'PNG', 15, 10, 60, 12); // y = 10 până la 25

// Mută textul mai jos decât imaginea
    doc.text("Dental Report", 20, 35); // începând de la y = 35
    doc.setFontSize(12);
    doc.text("This is a dental report.", 20, 45);

    let y = 40;

    // Parcurgem fiecare dinte și îl adăugăm în PDF
    teethWithImages.forEach((tooth, index) => {
        const toothTitle = `Tooth ${tooth.name}`;
        doc.setFont(undefined, "bold");
        doc.text(toothTitle, 20, y);
        y += 8;

        // Afișăm imaginea dacă există
        if (tooth.croppedImage) {
            const imageWidth = 40;
            const imageHeight = 40;

            // Dacă nu e loc pe pagină pentru imagine + text, adaugă pagină
            if (y + imageHeight + 10 > 270) {
                doc.addPage();
                y = 20;
            }

            doc.addImage(tooth.croppedImage, 'PNG', 25, y, imageWidth, imageHeight);
            y += imageHeight + 5;
        }

        doc.setFont(undefined, "normal");
        if (tooth.issues && tooth.issues.length > 0) {
            tooth.issues.forEach((issue) => {
                doc.text(`- ${issue.name}`, 25, y);
                y += 6;

                if (y > 270) {
                    doc.addPage();
                    y = 20;
                }
            });
        } else {
            doc.text("- No issues identified", 25, y);
            y += 6;
        }

        y += 6; // spațiu între dinți
    });

    const pdfBlob = doc.output("blob");
    const blobUrl = URL.createObjectURL(pdfBlob);
    window.open(blobUrl); // Deschide PDF în alt tab
};

// Convertor pentru fișier importat
const convertImgToBase64FromImport = (imgPath) => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.src = imgPath;

        img.onload = () => {
            const canvas = document.createElement("canvas");
            canvas.width = img.width;
            canvas.height = img.height;

            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0);

            const dataUrl = canvas.toDataURL("image/png");
            resolve(dataUrl);
        };

        img.onerror = (err) => reject("Failed to load image");
    });
};


/**
 * Creează o listă de dinti cu imagini croppuite pe baza poligonului.
 * @param {HTMLImageElement} panoramicImage - Radiografia panoramică
 * @param {Array} teethList - Lista de dinți, fiecare cu polygon
 * @returns {Promise<Array>} - Lista de dinți cu câmp nou: croppedImage (base64)
 */
export const cropTeethFromRadiograph = async (panoramicImage, teethList) => {
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");

    // Setăm dimensiunea canvasului cât imaginea panoramică
    canvas.width = panoramicImage.width;
    canvas.height = panoramicImage.height;

    ctx.drawImage(panoramicImage, 0, 0);

    const teethWithImages = await Promise.all(teethList.map(async (tooth) => {
        try {
            const polygon = JSON.parse(tooth.polygon); // asigură-te că este o listă de [x, y]

            const xs = polygon.map(p => p[0]);
            const ys = polygon.map(p => p[1]);

            const minX = Math.max(Math.min(...xs) - 5, 0); // mic padding
            const minY = Math.max(Math.min(...ys) - 5, 0);
            const maxX = Math.min(Math.max(...xs) + 5, canvas.width);
            const maxY = Math.min(Math.max(...ys) + 5, canvas.height);

            const width = maxX - minX;
            const height = maxY - minY;

            const toothCanvas = document.createElement("canvas");
            const toothCtx = toothCanvas.getContext("2d");

            toothCanvas.width = width;
            toothCanvas.height = height;

            toothCtx.drawImage(canvas, minX, minY, width, height, 0, 0, width, height);

            const croppedImage = toothCanvas.toDataURL("image/png");

            return {
                ...tooth,
                croppedImage,
            };
        } catch (error) {
            console.error(`Error cropping tooth ${tooth.name}`, error);
            return {
                ...tooth,
                croppedImage: null,
            };
        }
    }));

    return teethWithImages;
};
